/*
 * Name: build.mjs
 * Purpose: Regenerates the vendored, self-contained ExcelJS bundle (#690).
 * Created: 2026-09-19
 * Author: Michael K. Steinberg
 *
 * Usage: npm i --no-save exceljs@4.4.0 && node ui/vendor/exceljs/build.mjs
 *
 * `exceljs` is deliberately NOT a dependency of this repo -- vendoring the
 * bundle is the whole point. Install it ad-hoc to regenerate, then drop it.
 */

import { copyFileSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { build } from "esbuild";

const HERE = dirname(fileURLToPath(import.meta.url));
const require = createRequire(import.meta.url);

/** The version the committed bundle was produced from. */
const PINNED_VERSION = "4.4.0";

const pkg = require("exceljs/package.json");
if (pkg.version !== PINNED_VERSION) {
    throw new Error(
        `Refusing to build: exceljs ${pkg.version} is installed but the bundle ` +
            `is pinned to ${PINNED_VERSION}. Bump PINNED_VERSION here and in ` +
            `README.md deliberately, then rebuild.`,
    );
}

/**
 * Modules that only serve ExcelJS's on-disk file I/O: unzipper's
 * extract-to-directory (`fstream`), archiver's directory globbing (`glob`,
 * `readdir-glob`) and the streaming reader's temp files (`tmp`). The export builds an in-memory workbook buffer and
 * never reaches them, but their dynamic `path.resolve` / `fs` calls make Turbopack trace the
 * whole project (#777). Stubbed to a near-empty module; anything that
 * did call them would fail loudly on the missing method.
 */
const FS_ONLY_MODULES = /^(fstream|glob|readdir-glob|tmp)$/;

const stubFsOnlyModules = {
    name: "stub-fs-only-modules",
    setup(b) {
        b.onResolve({ filter: FS_ONLY_MODULES }, (args) => ({
            path: args.path,
            namespace: "stub-fs-only",
        }));
        b.onLoad({ filter: /.*/, namespace: "stub-fs-only" }, () => ({
            // `tmp` is configured at load time, so it needs this one no-op.
            contents: "module.exports = { setGracefulCleanup() {} };",
            loader: "js",
        }));
    },
};

// CJS, not ESM. ExcelJS is CommonJS and reaches for Node builtins through
// `require`. Bundling it to ESM makes esbuild emit a `require` shim, and
// Next.js's page-data collection rejects that outright with "dynamic usage of
// require is not supported" -- the export route fails to build even though the
// same bundle works fine under vitest. Emitting CJS keeps the requires as
// real requires, which Next's bundler resolves normally.
await build({
    entryPoints: [join(HERE, "entry.cjs")],
    bundle: true,
    format: "cjs",
    platform: "node",
    // The images run Node 24; node20 stays a conservative syntax floor.
    target: "node20",
    minify: true,
    legalComments: "none",
    plugins: [stubFsOnlyModules],
    outfile: join(HERE, "dist", "exceljs.bundle.cjs"),
});

// Vendor ExcelJS's own declarations rather than hand-writing a subset: they
// are a single self-contained file with no imports, so copying them keeps the
// types exact and free of drift.
const types = require.resolve("exceljs/index.d.ts");
copyFileSync(types, join(HERE, "dist", "exceljs.bundle.d.ts"));

// TypeScript resolves a `.cjs` specifier to a sibling `.d.cts`, so the
// bundle needs its own two-line declaration -- ExcelJS's copied `index.d.ts`
// describes the library's API, not this file's single `module.exports`.
writeFileSync(
    join(HERE, "dist", "exceljs.bundle.d.cts"),
    [
        "// Generated by build.mjs. The real ExcelJS types live in",
        "// exceljs.bundle.d.ts; this only describes the bundle's export shape.",
        "declare const bundled: { Workbook: unknown };",
        "export = bundled;",
        "",
    ].join("\n"),
);

const bundle = readFileSync(join(HERE, "dist", "exceljs.bundle.cjs"));
writeFileSync(
    join(HERE, "dist", "PROVENANCE.txt"),
    [
        `exceljs version : ${PINNED_VERSION}`,
        `bundle bytes    : ${bundle.length}`,
        `built by        : ui/vendor/exceljs/build.mjs`,
        "",
        "Regenerate with:",
        "  npm i --no-save exceljs@" + PINNED_VERSION,
        "  node ui/vendor/exceljs/build.mjs",
        "",
    ].join("\n"),
);

console.log(
    `Bundled exceljs ${PINNED_VERSION} -> ${(bundle.length / 1024).toFixed(0)}KB`,
);
